    #[test]
    fn side_effect_module_runs_once_with_single_or_duplicate_static_edges() {
        for duplicate in [false, true] {
            let dependency = program_module(
                "dependency",
                vec![
                    Constant::String(EcmaString::encode("count")),
                    Constant::Int32(0),
                    Constant::Int32(1),
                ],
                vec![function(
                    0,
                    2,
                    vec![
                        Instruction::LoadGlobal {
                            dst: reg(0),
                            name: cid(1),
                        },
                        Instruction::JumpIfFalse {
                            condition: reg(0),
                            target: pc(3),
                        },
                        Instruction::Jump { target: pc(5) },
                        Instruction::LoadConst {
                            dst: reg(0),
                            constant: cid(2),
                        },
                        Instruction::StoreGlobal {
                            name: cid(1),
                            value: reg(0),
                        },
                        Instruction::LoadConst {
                            dst: reg(1),
                            constant: cid(3),
                        },
                        Instruction::Binary {
                            dst: reg(0),
                            op: BinaryOp::Add,
                            left: reg(0),
                            right: reg(1),
                        },
                        Instruction::StoreGlobal {
                            name: cid(1),
                            value: reg(0),
                        },
                        Instruction::Return { value: reg(0) },
                    ],
                    Vec::new(),
                )],
                Vec::new(),
                vec![Binding {
                    name: cid(1),
                    kind: BindingKind::Hoisted,
                }],
                vec![Export {
                    name: cid(1),
                    source: ExportSource::Local(BindingId::new(0)),
                }],
            );
            let mut edges = vec![Edge {
                specifier: cid(2),
                target: EdgeTarget::Local(ModuleId::new(0)),
                kind: EdgeKind::Static,
            }];
            if duplicate {
                edges.push(Edge {
                    specifier: cid(3),
                    target: EdgeTarget::Local(ModuleId::new(0)),
                    kind: EdgeKind::Static,
                });
            }
            let root = program_module(
                "root",
                vec![
                    Constant::String(EcmaString::encode("count")),
                    Constant::String(EcmaString::encode("dep-one")),
                    Constant::String(EcmaString::encode("dep-two")),
                ],
                vec![function(
                    0,
                    1,
                    vec![
                        Instruction::LoadGlobal {
                            dst: reg(0),
                            name: cid(1),
                        },
                        Instruction::Return { value: reg(0) },
                    ],
                    Vec::new(),
                )],
                edges,
                vec![Binding {
                    name: cid(1),
                    kind: BindingKind::Imported {
                        edge: EdgeId::new(0),
                        name: cid(1),
                    },
                }],
                Vec::new(),
            );
            assert_eq!(
                run_ok(&linked(vec![dependency, root], 1)).value,
                Value::int32(1)
            );
        }
    }

